func TestWorkflowStatusMissingDatabaseDoesNotCreateStore(t *testing.T) {
	t.Parallel()
	dbPath := filepath.Join(t.TempDir(), "missing.db")
	var out bytes.Buffer

	cmd := newWorkflowStatusCmd(&rootFlags{})
	cmd.SetOut(&out)
	cmd.SetArgs([]string{"--db", dbPath})
	if err := cmd.Execute(); err != nil {
		t.Fatalf("workflow status returned error: %v", err)
	}
	if _, err := os.Stat(dbPath); !os.IsNotExist(err) {
		t.Fatalf("workflow status created or touched missing DB; stat err = %v", err)
	}
	if !strings.Contains(out.String(), "No archived data") {
		t.Fatalf("workflow status output = %q, want no-data message", out.String())
	}
}
